"""Generate the local-only historical LightGBM podium dashboard."""
from __future__ import annotations

import hashlib
import json
from pathlib import Path

import pandas as pd

from .rights import verify_prediction_provenance

RACE_ID = "201905040610"


def _hash(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as source:
        for chunk in iter(lambda: source.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _payload(ranking: Path, card_path: Path) -> dict:
    scores = pd.read_csv(ranking, dtype={"race_id": str, "horse_id": str}).fillna("")
    required = {"race_id", "horse_id", "horse_name", "predicted_rank", "reference_win_score", "model_version", "generated_at", "visibility", "name_verification"}
    if missing := required - set(scores): raise ValueError(f"Ranking CSV missing: {', '.join(sorted(missing))}")
    scores = scores.loc[scores.race_id.eq(RACE_ID)].copy()
    if len(scores) != 12 or set(pd.to_numeric(scores.predicted_rank, errors="coerce")) != set(range(1, 13)): raise ValueError("Saved ranking must contain ranks 1 through 12 exactly once")
    if not scores.name_verification.eq("CONFIRMED").all() or not scores.visibility.eq("LOCAL_INTERNAL_ONLY").all(): raise PermissionError("Only confirmed local-only ranking rows are displayable")
    models = scores.model_version.unique()
    if len(models) != 1: raise ValueError("Saved ranking has multiple model versions")
    verify_prediction_provenance(ranking, str(models[0]), "kblueleaf-jp-racing-horse-research")
    card = pd.read_csv(card_path, dtype={"race_id": str, "horse_id": str}).fillna("")
    needed = {"race_id", "horse_id", "horse_name", "gate_no", "horse_no", "jockey_name", "source_url", "confirmed_at", "verification_status"}
    if missing := needed - set(card): raise ValueError(f"Display CSV missing: {', '.join(sorted(missing))}")
    card = card.loc[card.race_id.eq(RACE_ID)].copy()
    if len(card) != 12 or card.horse_id.duplicated().any() or not card.verification_status.eq("CONFIRMED").all(): raise ValueError("Display CSV requires 12 unique confirmed runners")
    frame = scores.merge(card, on=["race_id", "horse_id", "horse_name"], validate="one_to_one")
    if len(frame) != 12: raise ValueError("Ranking and local display CSV do not match")
    frame["gate_no"] = pd.to_numeric(frame.gate_no, errors="raise").astype(int); frame["horse_no"] = pd.to_numeric(frame.horse_no, errors="raise").astype(int)
    if frame.horse_no.duplicated().any(): raise ValueError("Display CSV has duplicate horse numbers")
    utc = pd.Timestamp(scores.generated_at.iloc[0])
    return {"model": str(models[0]), "generated_at_utc": utc.isoformat(), "generated_at_jst": utc.tz_convert("Asia/Tokyo").strftime("%Y年%m月%d日 %H:%M:%S JST"), "csv": ranking.name, "sha256": _hash(ranking), "source": str(card.source_url.iloc[0]), "checked_at": str(card.confirmed_at.iloc[0]), "runners": [{"name": str(x.horse_name), "gate": int(x.gate_no), "number": int(x.horse_no), "jockey": str(x.jockey_name), "rank": int(x.predicted_rank), "score": float(x.reference_win_score)} for x in frame.sort_values("predicted_rank").itertuples(index=False)]}


def build_historical_local_demo(*, ranking_path: str | Path, display_fields_path: str | Path, output_path: str | Path) -> Path:
    ranking, card, output = Path(ranking_path), Path(display_fields_path), Path(output_path)
    root = Path("ai/quarantine").resolve()
    if any(root not in value.resolve().parents for value in (ranking, card, output)): raise PermissionError("All local-demo files must remain under ai/quarantine")
    data = json.dumps(_payload(ranking, card), ensure_ascii=False).replace("<", "\\u003c")
    html = f'''<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>KEIBA AI | 赤富士ステークス</title><style>
:root{{--bg:#031216;--panel:#092128;--panel2:#0d2b32;--line:#205b66;--green:#47ef70;--cyan:#27d9e8;--gold:#f0d478;--silver:#e4edf0;--bronze:#df9868;--ink:#f2faf5;--muted:#a4bdb8}}*{{box-sizing:border-box}}html{{scroll-behavior:smooth}}body{{margin:0;background:radial-gradient(circle at 60% -15%,#155156,transparent 35%),linear-gradient(125deg,#02090c,#061b20 63%,#031416);color:var(--ink);font-family:Inter,"Yu Gothic",system-ui,sans-serif}}.shell{{padding-left:88px;min-height:100vh}}.rail{{position:fixed;z-index:20;inset:0 auto 0 0;width:88px;background:linear-gradient(#06161b,#041014);border-right:1px solid #20505a;display:flex;align-items:center;flex-direction:column;gap:15px;padding:19px 0}}.logo{{width:42px;height:42px;display:grid;place-items:center;border:1px solid var(--cyan);border-radius:13px;color:var(--green);font-weight:900;font-size:20px;box-shadow:0 0 23px #27d9e84d}}.rail a{{display:grid;place-items:center;width:44px;height:44px;border:1px solid transparent;border-radius:12px;text-decoration:none;color:#9bb3b1;font-size:10px}}.rail a:hover,.rail a:first-of-type{{border-color:#2a9d94;color:var(--green);background:#0b3030}}.rail small{{margin-top:auto;color:#5f7a79;writing-mode:vertical-rl;font-size:9px;letter-spacing:.14em}}main{{max-width:1600px;margin:auto;padding:20px 30px 48px}}.header{{min-height:90px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #1a5962;margin-bottom:18px}}.brand{{font-size:13px;font-weight:900;letter-spacing:.13em;color:var(--cyan)}}.title{{font-size:clamp(30px,4vw,46px);letter-spacing:.04em;margin:5px 0 4px;font-weight:900}}.subtitle{{color:var(--muted);font-size:14px}}.badge{{color:var(--cyan);border:1px solid #25737c;border-radius:99px;padding:8px 12px;font-size:10px;letter-spacing:.08em}}.grid{{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(310px,.7fr);gap:16px}}.panel{{position:relative;overflow:hidden;background:linear-gradient(145deg,#0c2931e8,#07171de8);border:1px solid #1b4a55;border-radius:16px;padding:18px;box-shadow:0 14px 38px #0008;transition:.18s}}.panel:hover{{border-color:#2d8490;box-shadow:0 16px 42px #000a,0 0 18px #27d9e816}}.kicker{{color:var(--cyan);font-size:10px;font-weight:800;letter-spacing:.13em}}h2{{font-size:15px;margin:4px 0}}.muted{{color:var(--muted);font-size:12px;line-height:1.55}}.podium{{display:grid;grid-template-columns:1fr 1.23fr 1fr;align-items:end;gap:12px;margin-top:12px;min-height:224px}}.place{{position:relative;min-height:174px;border:1px solid #235562;border-radius:13px;padding:14px;background:linear-gradient(160deg,#0e3037,#092027);display:flex;flex-direction:column;justify-content:flex-end}}.place:hover{{box-shadow:0 0 21px #27d9e824}}.place.first{{min-height:218px;order:2;border-color:var(--gold);background:linear-gradient(160deg,#4c401c,#123429 72%,#092128);box-shadow:0 0 23px #f0d47825}}.place.second{{order:1;border-color:#b9ccd0}}.place.third{{order:3;border-color:var(--bronze)}}.place-rank{{position:absolute;top:13px;left:14px;color:var(--green);font-size:10px;letter-spacing:.1em}}.crown{{position:absolute;right:14px;top:10px;color:var(--gold);font-size:23px;filter:drop-shadow(0 0 6px #f0d47880)}}.place-name{{font-size:18px;font-weight:900;line-height:1.28}}.first .place-name{{font-size:24px}}.horse-meta{{font-size:12px;color:var(--muted);margin-top:7px;line-height:1.55}}.place-score{{margin-top:12px;color:var(--green);font-size:19px;font-weight:900;font-variant-numeric:tabular-nums}}.place-score small{{display:block;color:var(--muted);font-size:9px;font-weight:500;letter-spacing:.1em}}.info-stack{{display:grid;gap:8px;margin-top:12px}}.info{{padding:10px 11px;border-left:2px solid var(--green);background:#071d21;color:var(--muted);font-size:11px}}.info b{{display:block;color:var(--ink);font-size:13px;margin-top:4px;line-height:1.45;overflow-wrap:anywhere}}.source{{color:var(--cyan)}}.bar-panel{{margin-top:16px}}.score-bars{{display:grid;gap:8px;margin-top:14px}}.score-row{{display:grid;grid-template-columns:30px minmax(120px,190px) 1fr 76px;gap:9px;align-items:center;font-size:12px}}.score-rank{{font-weight:900;text-align:center}}.score-name{{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--ink);font-weight:700}}.track{{height:13px;border-radius:99px;background:#041216;border:1px solid #143d45;overflow:hidden}}.fill{{height:100%;border-radius:99px;background:linear-gradient(90deg,#16c7c9,var(--green));box-shadow:0 0 14px #47ef7052}}.fill.first{{background:linear-gradient(90deg,#bd932f,var(--gold))}}.fill.second{{background:linear-gradient(90deg,#93aeb4,var(--silver))}}.fill.third{{background:linear-gradient(90deg,#aa633c,var(--bronze))}}.score-value{{text-align:right;color:var(--green);font-variant-numeric:tabular-nums;font-weight:800}}.table-panel{{margin-top:16px;padding:0;overflow:auto}}.table-head{{padding:17px 18px 3px;display:flex;justify-content:space-between;align-items:end;gap:12px}}.tabs{{display:flex;gap:7px}}button{{cursor:pointer;background:#08242a;border:1px solid #25606b;color:var(--muted);padding:7px 10px;border-radius:8px;font-size:11px}}button[aria-pressed="true"]{{color:#06201d;background:var(--green);border-color:var(--green);font-weight:900}}table{{width:100%;border-collapse:collapse;min-width:720px}}th{{text-align:left;padding:13px 16px;background:#09262f;color:var(--cyan);font-size:10px;letter-spacing:.1em}}td{{padding:13px 16px;border-top:1px solid #183d46;font-size:13px}}tr:hover td{{background:#11323a}}.rank1{{color:var(--gold)}}.rank2{{color:var(--silver)}}.rank3{{color:var(--bronze)}}.frame{{display:inline-grid;place-items:center;width:24px;height:24px;border-radius:7px;font-size:11px;font-weight:900}}.f1{{background:#f7f7f1;color:#1b2425}}.f2{{background:#1d2427;color:#fff}}.f3{{background:#e74b45;color:#fff}}.f4{{background:#347ee8;color:#fff}}.f5{{background:#f0d450;color:#27250e}}.f6{{background:#32ab66;color:#fff}}.f7{{background:#ed9d43;color:#2f1d0c}}.f8{{background:#ef9fbb;color:#4a1630}}.model-grid{{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:16px}}.model-grid div{{padding:12px;border:1px solid #1d4d57;border-radius:10px;background:#071b21;color:var(--muted);font-size:10px;overflow-wrap:anywhere}}.model-grid b{{display:block;color:var(--ink);font-size:11px;margin-top:5px;line-height:1.45}}a{{color:var(--cyan)}}.menu{{display:none}}@media(max-width:920px){{.grid{{grid-template-columns:1fr}}.model-grid{{grid-template-columns:1fr 1fr}}}}@media(max-width:700px){{.shell{{padding-left:0}}.rail{{transform:translateX(-100%);transition:.2s}}.rail.open{{transform:none;box-shadow:16px 0 35px #000b}}.menu{{display:block;position:fixed;z-index:30;top:14px;left:14px;background:#0a252b;color:var(--cyan)}}main{{padding:75px 13px 28px}}.header{{display:block;padding-top:3px}}.badge{{display:inline-block;margin-top:10px}}.podium{{grid-template-columns:1fr;min-height:0}}.place,.place.first{{min-height:154px;order:unset}}.place.first{{order:1}}.place.second{{order:2}}.place.third{{order:3}}.score-row{{grid-template-columns:25px minmax(98px,125px) 1fr 65px;font-size:11px}}.model-grid{{grid-template-columns:1fr}}.table-head{{display:block}}.tabs{{margin-top:10px}}}}
</style><body><button class="menu" id="menu">☰</button><div class="shell"><aside class="rail" id="rail"><div class="logo">K</div><a href="#dashboard">HOME</a><a href="#ranking">RANK</a><a href="#analysis">SCORE</a><a href="#model">MODEL</a><small>LOCAL ONLY</small></aside><main><header id="dashboard" class="header"><div><div class="brand">● KEIBA AI · LOCAL RESEARCH DASHBOARD</div><div class="title">赤富士ステークス</div><div class="subtitle">東京10R　・　2019年10月19日　・　ダート 2,100m</div></div><span class="badge">LOCAL INTERNAL RESEARCH ONLY</span></header><section class="grid"><article class="panel"><div class="kicker">AI PREDICTION PODIUM</div><h2>AI予想 TOP 3</h2><p class="muted">保存済みLightGBM推論CSVの順位と参照スコアをそのまま表示</p><div id="podium" class="podium"></div></article><aside class="panel"><div class="kicker">RACE · MODEL SUMMARY</div><h2>レース・推論情報</h2><div class="info-stack" id="info"></div></aside></section><section class="panel bar-panel" id="analysis"><div class="kicker">SCORE COMPARISON</div><h2>全12頭のAI予想スコア</h2><p class="muted">順位順表示。予想スコアは勝率・的中確率ではありません。</p><div class="score-bars" id="bars"></div></section><section class="panel table-panel" id="ranking"><div class="table-head"><div><div class="kicker">FULL FIELD RANKING</div><h2>全頭AI予想ランキング</h2></div><div class="tabs"><button id="rankBtn" aria-pressed="true">AI順位順</button><button id="numberBtn" aria-pressed="false">馬番順</button></div></div><table><thead><tr><th>AI順位</th><th>枠</th><th>馬番</th><th>馬名</th><th>騎手</th><th>予想スコア</th></tr></thead><tbody id="rows"></tbody></table></section><section class="model-grid" id="model"></section></main></div><script type="application/json" id="payload">{data}</script><script>(()=>{{const d=JSON.parse(document.getElementById('payload').textContent),e=v=>String(v).replace(/[&<>'"]/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}}[c])),medal=r=>r===1?'👑':r===2?'🥈':'🥉',rc=r=>r===1?'rank1':r===2?'rank2':r===3?'rank3':'',fc=g=>`frame f${{g}}`;const podium=[d.runners[1],d.runners[0],d.runners[2]];podiumEl=document.getElementById('podium');podiumEl.innerHTML=podium.map(x=>`<article class="place ${{x.rank===1?'first':x.rank===2?'second':'third'}}"><div class="place-rank">${{x.rank}}位 ${{x.rank===1?'AI PREDICTION':'AI RANK'}}</div>${{x.rank===1?'<div class="crown">♛</div>':''}}<div class="place-name">${{e(x.name)}}</div><div class="horse-meta">${{e(x.jockey||'未確認')}}<br>${{x.gate}}枠　${{x.number}}番</div><div class="place-score"><small>AI PREDICTION SCORE</small>${{x.score.toFixed(6)}}</div></article>`).join('');const max=Math.max(...d.runners.map(x=>x.score));document.getElementById('bars').innerHTML=d.runners.map(x=>`<div class="score-row"><span class="score-rank ${{rc(x.rank)}}">${{x.rank}}位</span><span class="score-name">${{e(x.name)}}</span><div class="track"><div class="fill ${{x.rank===1?'first':x.rank===2?'second':x.rank===3?'third':''}}" style="width:${{(x.score/max*100).toFixed(2)}}%"></div></div><span class="score-value">${{x.score.toFixed(6)}}</span></div>`).join('');document.getElementById('info').innerHTML=`<div class="info">レース<b>赤富士ステークス<br>2019年10月19日・東京10R<br>ダート 2,100m</b></div><div class="info">LightGBMモデル<b>${{e(d.model)}}</b></div><div class="info">推論実行日時<b>${{e(d.generated_at_jst)}}<br><span class="muted">元: ${{e(d.generated_at_utc)}}</span></b></div><div class="info">出走馬・データ出典<b>確認済み 12頭<br><a class="source" href="${{e(d.source)}}">JRA公式成績表</a></b></div><div class="info">研究用デモ<b>2019年の実在レースを2026年に再推論した研究用デモ<br>LOCAL INTERNAL RESEARCH ONLY</b></div>`;let order='rank';function draw(){{const rows=[...d.runners].sort((a,b)=>order==='rank'?a.rank-b.rank:a.number-b.number);document.getElementById('rows').innerHTML=rows.map(x=>`<tr><td class="${{rc(x.rank)}}"><b>${{x.rank}}位 ${{x.rank<=3?medal(x.rank):''}}</b></td><td><span class="${{fc(x.gate)}}">${{x.gate}}</span></td><td>${{x.number}}</td><td><b>${{e(x.name)}}</b></td><td class="muted">${{e(x.jockey||'未確認')}}</td><td style="color:var(--green);font-weight:800">${{x.score.toFixed(6)}}</td></tr>`).join('');rankBtn.setAttribute('aria-pressed',order==='rank');numberBtn.setAttribute('aria-pressed',order==='number')}}rankBtn.onclick=()=>{{order='rank';draw()}};numberBtn.onclick=()=>{{order='number';draw()}};document.getElementById('model').innerHTML=`<div>MODEL VERSION<b>${{e(d.model)}}</b></div><div>INFERENCE TIME (JST)<b>${{e(d.generated_at_jst)}}</b></div><div>ORIGINAL TIMESTAMP (UTC)<b>${{e(d.generated_at_utc)}}</b></div><div>RANKING CSV / SHA-256<b>${{e(d.csv)}}<br>${{e(d.sha256)}}</b></div>`;menu.onclick=()=>rail.classList.toggle('open');document.querySelectorAll('.rail a').forEach(x=>x.onclick=()=>rail.classList.remove('open'));draw()}})()</script></body></html>'''
    # Grid items otherwise stretch to the height of their neighbour.  Keep the
    # podium panel content-sized even when the model-information panel is taller.
    html = html.replace("</style>", ".grid{align-items:start}.grid>.panel{align-self:start}</style>", 1)
    output.parent.mkdir(parents=True, exist_ok=True); output.write_text(html, encoding="utf-8")
    return output
